package com.example.airplanemode; import android.content.Context; import android.content.Intent; import android.content.IntentFilter; import android.os.Bundle; import androidx.appcompat.app.AppCompatActivity; public class MainActivity extends AppCompatActivity { final AirplaneModeReceiver receiver=new AirplaneModeReceiver(); @Override protected void onCreate(Bundle b){super.onCreate(b);setContentView(R.layout.activity_main);IntentFilter f=new IntentFilter(Intent.ACTION_AIRPLANE_MODE_CHANGED);if(android.os.Build.VERSION.SDK_INT>=33)registerReceiver(receiver,f,Context.RECEIVER_EXPORTED);else registerReceiver(receiver,f);} @Override protected void onDestroy(){try{unregisterReceiver(receiver);}catch(Exception ignored){}super.onDestroy();}}
